(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[5844],{2124:e=>{e.exports={page:"platform-info_page__Up36f",header:"platform-info_header__wYNwd",brand:"platform-info_brand__ZdPTX",hero:"platform-info_hero__wQU34",body:"platform-info_body__N_Kac",article:"platform-info_article__FU1WA",aside:"platform-info_aside__ycN4D",compact:"platform-info_compact__68Aqn",links:"platform-info_links__i1KDU",back:"platform-info_back__xXlS6",question:"platform-info_question__907H_",contact:"platform-info_contact__Su674",source:"platform-info_source___Dklx",footer:"platform-info_footer__bDSLN",skip:"platform-info_skip__tXO1f"}},5438:(e,a,o)=>{"use strict";o.d(a,{U:()=>n});let n={about:{ar:"عن المنصة",en:"About the platform",sections:[{ar:["حسابات أوضح، إدارة أسهل","منصة محاسبية تجمع الفواتير والعملاء والموردين والمخزون والقيود والتقارير في مساحة واحدة، بواجهة عربية وإنجليزية. تصميم محمد العقلة."],en:["Clarity for everyday business","A bilingual workspace for invoices, customers, suppliers, inventory, journals and reports. Designed by Mohammed Al-Oqleh."]},{ar:["لمن صُممت؟","لأصحاب الأعمال وفرق الحسابات الذين يحتاجون إلى تنظيم عملياتهم وفهم حركة أعمالهم. النسخة العامة تتيح استكشاف تجربة الاستخدام ببيانات تجريبية."],en:["Who is it for?","Business owners and accounting teams who want to organise operations and understand business activity. The public edition lets you explore the experience with sample data."]}]},benefits:{ar:"كيف تستفيد منها؟",en:"How it helps",sections:[{ar:["١. جهّز مساحة العمل","تعرّف على إعدادات الشركة والعملات والمستودعات والحسابات، ثم أضف بيانات تجريبية للعملاء والموردين والأصناف."],en:["1. Set up your workspace","Explore company settings, currencies, warehouses and accounts, then add sample customers, suppliers and items."]},{ar:["٢. تابع العمليات اليومية","استكشف المبيعات والمشتريات والمدفوعات وحركة المخزون من واجهات مترابطة. راجع المدخلات قبل تسجيل أي عملية."],en:["2. Follow daily operations","Explore sales, purchases, payments and inventory through connected screens. Review inputs before recording a transaction."]},{ar:["٣. اقرأ النتائج","استخدم ميزان المراجعة وتقارير المخزون والأرصدة لفهم النتائج. قارن التقارير بالمستندات الأصلية قبل اعتمادها في العمل الفعلي."],en:["3. Understand the results","Use trial balance, inventory and balance reports to understand activity. Reconcile reports with source documents before relying on them for real business."]}]},vision:{ar:"رؤيتنا",en:"Our vision",sections:[{ar:["تجربة تتجاوز اللغة","نسعى إلى جعل إدارة الحسابات مفهومة وسهلة الوصول، مع دعم العربية والإنجليزية واتجاهي القراءة وتصميم يناسب الشاشات المختلفة."],en:["An experience across languages","Our goal is approachable accounting with Arabic and English, both reading directions and layouts for different screen sizes."]},{ar:["تطوير يستند إلى الاحتياج","نطوّر التجربة عبر الملاحظات العملية: وضوح البيانات وسهولة التنقل ودقة التحقق. هذه رؤية للتطوير، وليست ادعاءً بشهادات اعتماد أو امتثال لجميع البلدان."],en:["Development driven by real needs","We improve through practical feedback: clear data, simple navigation and sound validation. This is a development vision, not a claim of certification or compliance in every country."]}]},faq:{ar:"الأسئلة الشائعة",en:"Frequently asked questions",sections:[{ar:["ما الذي يمكنني إدارته من خلال النظام؟","يمكنك إدارة المبيعات والمشتريات والعملاء والموردين والمخزون والمستودعات والقيود المحاسبية والمدفوعات والتقارير المالية من مكان واحد."],en:["What can I manage in the system?","You can manage sales, purchases, customers, suppliers, inventory, warehouses, journals, payments and financial reports from one workspace."]},{ar:["هل يدعم النظام العربية والإنجليزية؟","نعم. الواجهة تدعم العربية والإنجليزية مع اتجاه RTL وLTR، ويمكن التبديل بين اللغتين من الواجهة."],en:["Does the system support Arabic and English?","Yes. The interface supports Arabic and English with RTL and LTR layouts, and you can switch languages from the interface."]},{ar:["هل يمكن إدارة أكثر من شركة؟","نعم. النظام يدعم العمل على أكثر من شركة مع صلاحيات وأدوار مختلفة للمستخدمين، بحسب إعداد كل شركة."],en:["Can I manage more than one company?","Yes. The system supports multiple companies with different user roles and permissions according to each company setup."]},{ar:["هل تتوفر تقارير مالية ومخزون؟","نعم. يتضمن النظام تقارير مثل ميزان المراجعة، الأرباح والخسائر، المركز المالي، أعمار الذمم، وتقييم المخزون، إضافة إلى متابعة حركة الأصناف والمستودعات."],en:["Are financial and inventory reports available?","Yes. The system includes reports such as trial balance, profit and loss, balance sheet, aging and inventory valuation, along with item and warehouse movement tracking."]}]},privacy:{ar:"الخصوصية والبيانات",en:"Privacy & data",sections:[{ar:["نطاق هذه الصفحة","تشرح هذه الصفحة سلوك النسخة العامة المنشورة على GitHub Pages. عند تشغيل نسخة متصلة بخادم، تُرسل عمليات الحسابات إلى ذلك الخادم وتخضع بياناتها لإدارة الجهة المشغلة. آخر تحديث: 12 سبتمبر 2026."],en:["Scope of this notice","This notice describes the public GitHub Pages edition. In a server-connected installation, accounting requests are sent to that server and its operator manages the records. Updated: 12 September 2026."]},{ar:["ما الذي يحفظه المتصفح؟","تستخدم المعاينة التخزين المحلي لحفظ بيانات العمليات التجريبية، والجلسة، والشركة المختارة، وتفضيل اللغة، وقيم تحقق كلمة مرور المعاينة عند تغييرها. لا تُشفّر سجلات المعاينة المخزنة محليًا؛ تجنب إدخال بيانات حقيقية أو حساسة."],en:["What is stored in your browser?","The preview uses local storage for sample transactions, the session, selected company, language preference and preview password verification values when changed. Locally stored preview records are not encrypted; avoid real or sensitive data."]},{ar:["الاستضافة والتواصل","لا تتضمن الواجهة الحالية أدوات إعلانات أو تحليلات مضافة من طرفنا. قد تجمع GitHub معلومات تقنية عن الزيارات، ومنها عنوان IP لأغراض الأمان. عند مراسلتنا بالبريد، تُعالج رسالتك ومعلومات تواصلك للرد عليها عبر مزود البريد."],en:["Hosting and contact","The current interface includes no advertising or analytics tools added by us. GitHub may collect technical visit information, including IP addresses for security. When you email us, your message and contact details are processed through the email provider to respond."]},{ar:["الاحتفاظ والتحكم","تبقى بيانات المعاينة في المتصفح حتى حذفها أو إزالتها بواسطة المتصفح. تسجيل الخروج يزيل الجلسة والشركة المختارة، ولا يحذف سجلات المعاينة. صفحة إدارة البيانات تشرح خياراتك؛ لا نمسح سجلاتك تلقائيًا عند فتح هذه الصفحات."],en:["Retention and control","Preview records remain until you or your browser remove them. Signing out removes the session and selected company, but not preview records. The data guide explains your options; opening these pages does not erase records."]},{ar:["طلبات الخصوصية","للاستفسار عن رسالة أرسلتها إلينا أو لطلب تصحيحها أو حذفها، تواصل عبر info.moqleh@yahoo.com. سجلات المعاينة المحلية لا تصل إلينا تلقائيًا ولا يمكننا حذفها عن بُعد."],en:["Privacy requests","For questions about a message you sent us, or to request its correction or deletion, contact info.moqleh@yahoo.com. Local preview records are not automatically sent to us and cannot be removed by us remotely."]}]},data:{ar:"إدارة بياناتك",en:"Manage your data",sections:[{ar:["تسجيل الخروج","استخدم زر تسجيل الخروج داخل البرنامج لإنهاء الجلسة على هذا المتصفح. تبقى بيانات التجربة محفوظة؛ تسجيل الخروج ليس حذفًا للحساب أو للسجلات."],en:["Sign out","Use the sign-out button inside the app to end the session in this browser. Sample records remain; signing out does not delete an account or its records."]},{ar:["حذف بيانات المعاينة المحلية","بعد الاحتفاظ بما تحتاجه، افتح إعدادات المتصفح ← الخصوصية وبيانات المواقع ← ابحث عن moqleh.github.io ← امسح بيانات الموقع. هذا قد يحذف بيانات مواقع أخرى على نفس النطاق، ويعيد تفضيلات وكلمة مرور المعاينة المحلية؛ لا توجد استعادة تلقائية."],en:["Remove local preview data","After keeping what you need, open browser settings → privacy and site data → find moqleh.github.io → clear site data. This may also remove data for other sites on the same origin and reset local preview preferences and password settings. There is no automatic recovery."]},{ar:["عند استخدام خادم فعلي","مسح بيانات المتصفح لا يحذف البيانات من قاعدة بيانات الخادم. راجع مسؤول شركتك بخصوص الصلاحيات والاحتفاظ بالسجلات والنسخ الاحتياطية وطلبات الحذف."],en:["When using a real server","Clearing browser data does not delete server database records. Contact your company administrator about permissions, retention, backups and deletion requests."]}]},terms:{ar:"شروط الاستخدام",en:"Terms of use",sections:[{ar:["استخدام مسؤول","استخدم المنصة في الأعمال المصرح لك بها فقط، وأدخل بيانات تملك حق استخدامها. لا تحاول الوصول إلى حسابات الغير أو تعطيل الخدمة أو إساءة استخدامها. آخر تحديث: 12 سبتمبر 2026."],en:["Responsible use","Use the platform only for authorised activities and data you have permission to use. Do not access other accounts, disrupt the service or misuse it. Updated: 12 September 2026."]},{ar:["حدود المعاينة","النسخة العامة مخصصة للتجربة. قد تتغير الوظائف، وقد تفقد البيانات المحلية عند مسح المتصفح. لا تتضمن المعاينة ضمان توافر مستمر أو خدمة نسخ احتياطي أو دعم بزمن استجابة محدد."],en:["Preview limitations","The public edition is for evaluation. Features may change, and browser data can be lost when cleared. The preview includes no guaranteed uptime, backup service or fixed support response time."]},{ar:["مراجعة النتائج","راجع المدخلات والتقارير قبل استخدامها. المنصة لا تقدم استشارة محاسبية أو ضريبية أو قانونية، ولا يغني استخدامها عن مراجعة مختص ومتطلبات الجهة المعنية في بلدك."],en:["Review the results","Check inputs and reports before use. The platform does not provide accounting, tax or legal advice and does not replace professional review or requirements applicable in your country."]},{ar:["التحديثات والاستفسارات","نوضح التغييرات في هذه الصفحة عند تحديث قواعد الاستخدام. للاستفسار عن الاستخدام أو الإبلاغ عن مشكلة، استخدم صفحة التواصل. لا تتضمن هذه الصفحة تنازلاً عن حقوق يقررها القانون الواجب التطبيق."],en:["Updates and questions","Changes to usage rules will be reflected here. Use the contact page for questions or issues. This page does not waive rights provided by applicable law."]}]},contact:{ar:"تواصل معنا",en:"Contact us",sections:[{ar:["نستمع لملاحظاتك","للاقتراحات والدعم والاستفسارات المتعلقة بالخصوصية، تواصل مع محمد العقلة عبر البريد أو الهاتف أدناه. صف احتياجك بوضوح وسنراجع رسالتك."],en:["We welcome your feedback","For suggestions, support or privacy questions, contact Mohammed Al-Oqleh by email or phone below. Describe your request clearly so we can review it."]},{ar:["ماذا ترسل؟","اسم الصفحة ووصف المشكلة وخطوات تكرارها كافية للبدء. لا ترسل كلمات المرور أو رموز الدخول أو ملفات العملاء المحاسبية."],en:["What should you send?","Start with the page name, issue description and steps to reproduce it. Do not send passwords, sign-in codes or customer accounting files."]}]}}},5844:(e,a,o)=>{"use strict";o.d(a,{v:()=>b});var n=o(5892),s=o(518),r=o.n(s),t=o(7608),i=o(2232),c=o(7488),l=o(780),d=o(9904),u=o(6941),p=o(8515),h=o(363),m=o(5438),f=o(2124),g=o.n(f);let y=[t.A,i.A,c.A,l.A,d.A,u.A,p.A,h.A];function b(e){let{ar:a,compact:o=!1}=e;return(0,n.jsx)("nav",{className:o?g().compact:g().links,"aria-label":a?"عن المنصة والمساعدة":"Platform information and help",children:Object.entries(m.U).map((e,o)=>{let[s,t]=e,i=y[o];return(0,n.jsxs)(r(),{href:"/information/".concat(s,"/").concat(a?"":"?lang=en"),children:[(0,n.jsx)(i,{size:20,"aria-hidden":"true"}),(0,n.jsx)("span",{children:a?t.ar:t.en})]},s)})})}}}]);